    // ── KG-ISF-COMPLETENESS.1a — structural precision agent-identity gate ────────────────────
    #[test]
    fn actor_identity_gate_rejects_function_word_and_verb_led_fragments() {
        // The designed Class-A targets (the agent surface fidelity measurement) plus a sample of
        // the function-word/verb-led fragments the corpus census surfaced. All are phrase
        // fragments, never agents.
        for fragment in [
            "For",
            "For components",
            "Then it",
            "with write",
            "is recommended",
            "is permitted",
            "ensures",
            "Exit from",
            "next",
            "next access",
            "does not",
            "used to",
            "to back",
            "are coherent",
            "of ordered",
            "In both",
            "indicates",
            "required behavior",
        ] {
            assert!(
                super::is_non_actor_phrase_fragment(fragment),
                "{fragment:?} should be rejected as a non-agent phrase fragment"
            );
            assert!(
                super::normalize_relation_actor_name(fragment).is_none(),
                "{fragment:?} must not survive the relation-actor seam"
            );
        }
    }

    #[test]
    fn actor_identity_gate_keeps_real_agents_and_class_b_fragments() {
        // Real protocol agents must survive — and so must Class-B fragments (subject + trailing
        // verb/adverb), because `.1b` (not `.1a`) consolidates those to their leading noun. The
        // gate is verb-LED only, so a leading NOUN keeps the candidate.
        for keep in [
            "Manager",
            "Subordinate",
            "Requester",
            "Completer",
            "Transmitter",
            "Receiver",
            "interconnect",
            "Multiplexor",
            "Exclusive Access Monitor",
            // Class-B fragments (preserved for `.1b` consolidation, never dropped here):
            "Subordinate extends",
            "Subordinate then",
            "address decoder",
            "decoder also",
            "Transmitter interface",
            // Acronym agent whose lowercase collides with a pronoun we deliberately excluded:
            "ITS",
        ] {
            assert!(
                !super::is_non_actor_phrase_fragment(keep),
                "{keep:?} is a real agent (or a Class-B fragment) and must NOT be gated by .1a"
            );
        }
        // The seam keeps a real agent unchanged, and now CONSOLIDATES a Class-B trailing fragment to
        // its leading agent noun (KG-ISF-COMPLETENESS.1b.i) rather than only preserving it.
        assert_eq!(
            super::normalize_relation_actor_name("Manager").as_deref(),
            Some("Manager")
        );
        assert_eq!(
            super::normalize_relation_actor_name("Subordinate extends").as_deref(),
            Some("Subordinate")
        );
    }

    // ── KG-ISF-COMPLETENESS.1b.i — Class-B trailing-fragment consolidation ────────────────────
    #[test]
    fn trailing_fragment_consolidation_strips_to_the_leading_agent_noun() {
        // Trailing verb / discourse-adverb residue is stripped; the leading agent noun is kept, so the
        // relation re-attributes onto the real agent. Mirrors the measured wire-doc Class-B fragments.
        for (fragment, canonical) in [
            ("Subordinate extends", "Subordinate"),
            ("Subordinate then", "Subordinate"),
            ("decoder also", "decoder"),
            ("register allows", "register"),
            ("register contains", "register"),
        ] {
            assert_eq!(
                super::consolidate_trailing_fragment(fragment),
                canonical,
                "{fragment:?} should consolidate to {canonical:?}"
            );
            assert_eq!(
                super::normalize_relation_actor_name(fragment).as_deref(),
                Some(canonical),
                "{fragment:?} must re-attribute onto {canonical:?} through the relation-actor seam"
            );
        }
        // A real agent (no trailing residue) is returned byte-identical — protects the byte-stability
        // guarantee for fragment-free documents.
        for keep in [
            "Manager",
            "Subordinate",
            "Exclusive Access Monitor",
            "address decoder",
        ] {
            assert_eq!(super::consolidate_trailing_fragment(keep), keep);
        }
        // Never strips below the leading noun, and a conjunction is NOT a trailing strip target (it is
        // a coordinated-subject remnant for `.1b.iii`).
        assert_eq!(
            super::consolidate_trailing_fragment("Subordinate and"),
            "Subordinate and"
        );
        // A consolidated head that is itself a function word is then rejected by the `.1a` gate.
        assert!(super::normalize_relation_actor_name("does not").is_none());
        assert!(super::normalize_relation_actor_name("It also").is_none());
    }

    #[test]
    fn trailing_discourse_markers_are_known_leading_words() {
        // Drift-guard: the trailing-strip discourse-marker set is a SUBSET of the leading function-word
        // lexicon (same universal grammar, different structural role). If one list is edited without the
        // other, this fails — keeping the two lexicons from silently diverging.
        for marker in super::NON_ACTOR_TRAILING_DISCOURSE_MARKERS {
            assert!(
                super::NON_ACTOR_LEADING_FUNCTION_WORDS.contains(marker),
                "{marker:?} must also be a known leading function word"
            );
        }
    }

    // ── KG-ISF-COMPLETENESS.1c.i — dense-prose trailing preposition/auxiliary strip ───────────
    #[test]
    fn trailing_function_words_are_known_leading_non_conjunctions() {
        // Drift-guard (mirrors the discourse-marker guard): every trailing-strip function word is a
        // known LEADING function word (same universal grammar, different structural role), AND none is a
        // coordinating/subordinating conjunction — a trailing `and`/`or` is a coordinated-subject remnant
        // that `.1b.iii` splits, never strips. Editing one lexicon without the other fails here.
        const CONJUNCTIONS: &[&str] = &[
            "and", "or", "nor", "but", "so", "because", "if", "unless", "although", "though",
            "whether", "since", "while", "whereas", "yet",
        ];
        for word in super::NON_ACTOR_TRAILING_FUNCTION_WORDS {
            assert!(
                super::NON_ACTOR_LEADING_FUNCTION_WORDS.contains(word),
                "{word:?} must also be a known leading function word"
            );
            assert!(
                !CONJUNCTIONS.contains(word),
                "{word:?} is a conjunction — trailing conjunctions belong to .1b.iii, not the strip"
            );
        }
    }

    #[test]
    fn trailing_function_word_consolidation_strips_aux_and_prep_to_leading_agent() {
        // Dense-prose residue: a trailing preposition or auxiliary/modal off a leading agent noun is
        // stripped so the relation re-attributes onto the real agent. Mirrors the measured eMMC
        // fragments (`docs/research/agent-identity-prose-class-measurement.md`): the `host *` variants
        // collapse onto `host`.
        for (fragment, canonical) in [
            ("host has", "host"),
            ("host to", "host"),
            ("host is", "host"),
            ("host with", "host"),
            ("cache in", "cache"),
            ("device to", "device"),
            ("Manager must", "Manager"),
        ] {
            assert_eq!(
                super::consolidate_trailing_fragment(fragment),
                canonical,
                "{fragment:?} should consolidate to {canonical:?}"
            );
            assert_eq!(
                super::normalize_relation_actor_name(fragment).as_deref(),
                Some(canonical),
                "{fragment:?} must re-attribute onto {canonical:?} through the relation-actor seam"
            );
        }
        // A junk-head fragment is normalized (its trailing prep stripped) but NOT recovered to a real
        // agent — that bare-noun-precision case is the deferred `.1c.ii`, not this strip. Still a strict
        // improvement (no worse than the pre-strip fragment) and never fabricated.
        assert_eq!(
            super::consolidate_trailing_fragment("advantage of"),
            "advantage"
        );
        // A trailing conjunction is STILL not a strip target (coordinated-subject remnant for `.1b.iii`).
        assert_eq!(
            super::consolidate_trailing_fragment("Subordinate and"),
            "Subordinate and"
        );
        // Real agents with no trailing residue stay byte-identical — protects WIRE-BASED-100 byte-stability.
        for keep in [
            "Manager",
            "Subordinate",
            "host",
            "interconnect",
            "Exclusive Access Monitor",
        ] {
            assert_eq!(super::consolidate_trailing_fragment(keep), keep);
        }
    }

    // ── KG-ISF-COMPLETENESS.1b.iii — coordinated-subject split ───────────────────────────────
    #[test]
    fn coordinated_subject_splits_into_real_conjuncts() {
        // "X and Y" → both real agents (mirrors the measured AHB coordinated fragments).
        assert_eq!(
            super::split_coordinated_actor_subject("Subordinate and decoder"),
            vec!["Subordinate".to_string(), "decoder".to_string()]
        );
        assert_eq!(
            super::split_coordinated_actor_subject("Exclusive Access Monitor and Subordinate"),
            vec![
                "Exclusive Access Monitor".to_string(),
                "Subordinate".to_string()
            ]
        );
        // A disjunction is ambiguous — NEVER split (would fabricate a relation for an agent that may not act).
        assert!(super::split_coordinated_actor_subject("Manager or Subordinate").is_empty());
        // Not a coordination at all → no split.
        assert!(super::split_coordinated_actor_subject("Subordinate").is_empty());
        // A conjunct that fails the agent gate is dropped; <2 survivors means the caller keeps the original.
        assert_eq!(
            super::split_coordinated_actor_subject("Subordinate and for"),
            vec!["Subordinate".to_string()]
        );
    }

    #[test]
    fn coordinated_relation_post_pass_attributes_to_both_agents() {
        use crate::ir::source::{ActorSignalRelation, AutomationConfidence, RelationKind};
        let coordinated = ActorSignalRelation {
            relation_id: "chk_asr_0007".to_string(),
            actor_name: "Subordinate and decoder".to_string(),
            signal_name: "HADDR".to_string(),
            relation: RelationKind::Reads,
            source_statement_ids: vec!["stmt_42".to_string()],
            automation_confidence: AutomationConfidence::Medium,
        };
        let plain = ActorSignalRelation {
            relation_id: "chk_asr_0008".to_string(),
            actor_name: "Manager".to_string(),
            signal_name: "HWUSER".to_string(),
            relation: RelationKind::Drives,
            source_statement_ids: vec!["stmt_43".to_string()],
            automation_confidence: AutomationConfidence::Medium,
        };
        let out = super::split_coordinated_actor_relations(vec![coordinated, plain.clone()]);
        // The coordinated relation became one per conjunct (signal/relation/provenance preserved, ids unique),
        // and the plain relation passed through untouched.
        assert_eq!(out.len(), 3);
        assert_eq!(out[0].actor_name, "Subordinate");
        assert_eq!(out[0].relation_id, "chk_asr_0007__subordinate");
        assert_eq!(out[1].actor_name, "decoder");
        assert_eq!(out[1].relation_id, "chk_asr_0007__decoder");
        for r in &out[..2] {
            assert_eq!(r.signal_name, "HADDR");
            assert!(matches!(r.relation, RelationKind::Reads));
            assert_eq!(r.source_statement_ids, vec!["stmt_42".to_string()]);
        }
        assert_eq!(out[2].actor_name, "Manager");
        assert_eq!(out[2].relation_id, "chk_asr_0008");
    }

    // KG-ISF-COMPLETENESS.1b.ii — `strip_interface_suffix` returns the leading block only for a real
    // trailing " interface", and never for a mid-string or bare occurrence.
